const _astro_dataLayerContent = [["Map",1,2,9,10,349,350],"meta::meta",["Map",3,4,5,6,7,8],"astro-version","5.18.2","content-config-digest","05c3ac8960f6fcdf","astro-config-digest","{\"root\":{},\"srcDir\":{},\"publicDir\":{},\"outDir\":{},\"cacheDir\":{},\"site\":\"https://atrari-pro.github.io/studio-jannah\",\"compressHTML\":true,\"base\":\"/\",\"trailingSlash\":\"never\",\"output\":\"static\",\"scopedStyleStrategy\":\"attribute\",\"build\":{\"format\":\"directory\",\"client\":{},\"server\":{},\"assets\":\"_astro\",\"serverEntry\":\"entry.mjs\",\"redirects\":true,\"inlineStylesheets\":\"auto\",\"concurrency\":1},\"server\":{\"open\":false,\"host\":false,\"port\":4321,\"streaming\":true,\"allowedHosts\":[]},\"redirects\":{},\"image\":{\"endpoint\":{\"route\":\"/_image\"},\"service\":{\"entrypoint\":\"astro/assets/services/sharp\",\"config\":{}},\"domains\":[],\"remotePatterns\":[],\"responsiveStyles\":false},\"devToolbar\":{\"enabled\":true},\"markdown\":{\"syntaxHighlight\":{\"type\":\"shiki\",\"excludeLangs\":[\"math\"]},\"shikiConfig\":{\"langs\":[],\"langAlias\":{},\"theme\":\"github-dark\",\"themes\":{},\"wrap\":false,\"transformers\":[]},\"remarkPlugins\":[],\"rehypePlugins\":[],\"remarkRehype\":{},\"gfm\":true,\"smartypants\":true},\"security\":{\"checkOrigin\":true,\"allowedDomains\":[],\"actionBodySizeLimit\":1048576},\"env\":{\"schema\":{},\"validateSecrets\":false},\"experimental\":{\"clientPrerender\":false,\"contentIntellisense\":false,\"headingIdCompat\":false,\"preserveScriptOrder\":false,\"liveContentCollections\":false,\"csp\":false,\"staticImportMetaEnv\":false,\"chromeDevtoolsWorkspace\":false,\"failOnPrerenderConflict\":false,\"svgo\":false},\"legacy\":{\"collections\":false}}","insights",["Map",11,12,57,58,97,98,140,141,180,181,223,224,264,265,307,308],"attribution-zero-clic",{id:11,data:13,body:31,filePath:32,digest:33,rendered:34},{title:14,description:15,publishedAt:16,status:17,tags:18,hook:23,sources:24},"Attribution multi-touch après zéro-clic : arrêtez d’attendre le modèle parfait","Quand une partie du parcours vit dans les LLM, le last-click agonise. Fiction Mag sur ce qu’il reste à mesurer.",["Date","2026-07-15T00:00:00.000Z"],"published",[19,20,21,22],"attribution","geo","llm","fiction","Le débat ‘quel modèle d’attribution ?’ masque souvent une collecte trop pauvre pour trancher.",[25,28],{label:26,url:27},"Google — Attribution (Analytics help)","https://support.google.com/analytics/answer/10596866",{label:29,url:30},"Empirik — vision GEO / zéro-clic","https://www.empirik.fr/agence-geo/","**Contenu fictif / illustratif** Jannah Mag.\n\n## Ce qui disparaît du radar\n\nUne part des utilisateurs arrive “déjà décidée” après une réponse ChatGPT / AI Overview. Pas de campagne. Pas de session longue. Juste une conversion… ou rien.\n\n## Ce qu’on peut encore faire\n\n- Marquer les landings “assistées LLM” (UTM / first-party quand c’est possible).\n- Réconcilier CRM (lead source déclarée vs analytics).\n- Accepter des **zones grises** plutôt que des modèles à 12 touches fictives.\n\n## Angle Studio Jannah\n\nOn préfère un **petit set d’events justes** + réconciliation métier à une usine d’attribution cosmétique. Le Mag le répétera : pas de modèle sexy sur un signal pourri.","content/insights/attribution-zero-clic.md","459f8182c105d0b1",{html:35,metadata:36},"<p><strong>Contenu fictif / illustratif</strong> Jannah Mag.</p>\n<h2 id=\"ce-qui-disparaît-du-radar\">Ce qui disparaît du radar</h2>\n<p>Une part des utilisateurs arrive “déjà décidée” après une réponse ChatGPT / AI Overview. Pas de campagne. Pas de session longue. Juste une conversion… ou rien.</p>\n<h2 id=\"ce-quon-peut-encore-faire\">Ce qu’on peut encore faire</h2>\n<ul>\n<li>Marquer les landings “assistées LLM” (UTM / first-party quand c’est possible).</li>\n<li>Réconcilier CRM (lead source déclarée vs analytics).</li>\n<li>Accepter des <strong>zones grises</strong> plutôt que des modèles à 12 touches fictives.</li>\n</ul>\n<h2 id=\"angle-studio-jannah\">Angle Studio Jannah</h2>\n<p>On préfère un <strong>petit set d’events justes</strong> + réconciliation métier à une usine d’attribution cosmétique. Le Mag le répétera : pas de modèle sexy sur un signal pourri.</p>",{headings:37,localImagePaths:48,remoteImagePaths:49,frontmatter:50,imagePaths:56},[38,42,45],{depth:39,slug:40,text:41},2,"ce-qui-disparaît-du-radar","Ce qui disparaît du radar",{depth:39,slug:43,text:44},"ce-quon-peut-encore-faire","Ce qu’on peut encore faire",{depth:39,slug:46,text:47},"angle-studio-jannah","Angle Studio Jannah",[],[],{title:14,description:15,publishedAt:51,status:17,hook:23,tags:52,sources:53},["Date","2026-07-15T00:00:00.000Z"],[19,20,21,22],[54,55],{label:26,url:27},{label:29,url:30},[],"ia-marketing-casse-tracking",{id:57,data:59,body:75,filePath:76,digest:77,rendered:78},{title:60,description:61,publishedAt:62,status:17,tags:63,hook:67,sources:68},"IA marketing : 7 automatisations qui cassent votre tracking (avant d’aider)","Chatbots, ranking bids, personalisation — ce que l’IA casse dans le dataLayer si personne ne regarde. Fiction Mag.",["Date","2026-07-18T00:00:00.000Z"],[64,65,66,22],"ia","tracking","activation","L’IA promet de scaler l’activation. Sur le terrain, elle scale aussi les événements mal nommés.",[69,72],{label:70,url:71},"Google — GA4 event tracking","https://developers.google.com/analytics/devguides/collection/ga4/events",{label:73,url:74},"W3C — privacy principles (cadre)","https://www.w3.org/TR/privacy-principles/","**Contenu fictif / illustratif.**\n\n## Sept façons de se tirer une balle (scénarios Mag)\n\n1. Chatbot qui ouvre 12 pages virtuelles sans convention de naming.\n2. Personnalisation qui change le DOM et casse les sélecteurs GTM.\n3. Bids auto branchés sur une conversion **doublon**.\n4. Scoring IA alimenté par des cookies pré-consent.\n5. “Content IA” sans URLs stables → SEO/GEO et analytics divergents.\n6. Webhooks non dédupliqués vers Ads.\n7. Aucun owner du **dictionnaire d’events**.\n\n## La chute\n\nAvant d’activer un copilote marketing, figez le contrat dataLayer. Chez Studio Jannah, l’IA arrive **après** le signal — pas à la place.","content/insights/ia-marketing-casse-tracking.md","c3908cb602f267d5",{html:79,metadata:80},"<p><strong>Contenu fictif / illustratif.</strong></p>\n<h2 id=\"sept-façons-de-se-tirer-une-balle-scénarios-mag\">Sept façons de se tirer une balle (scénarios Mag)</h2>\n<ol>\n<li>Chatbot qui ouvre 12 pages virtuelles sans convention de naming.</li>\n<li>Personnalisation qui change le DOM et casse les sélecteurs GTM.</li>\n<li>Bids auto branchés sur une conversion <strong>doublon</strong>.</li>\n<li>Scoring IA alimenté par des cookies pré-consent.</li>\n<li>“Content IA” sans URLs stables → SEO/GEO et analytics divergents.</li>\n<li>Webhooks non dédupliqués vers Ads.</li>\n<li>Aucun owner du <strong>dictionnaire d’events</strong>.</li>\n</ol>\n<h2 id=\"la-chute\">La chute</h2>\n<p>Avant d’activer un copilote marketing, figez le contrat dataLayer. Chez Studio Jannah, l’IA arrive <strong>après</strong> le signal — pas à la place.</p>",{headings:81,localImagePaths:88,remoteImagePaths:89,frontmatter:90,imagePaths:96},[82,85],{depth:39,slug:83,text:84},"sept-façons-de-se-tirer-une-balle-scénarios-mag","Sept façons de se tirer une balle (scénarios Mag)",{depth:39,slug:86,text:87},"la-chute","La chute",[],[],{title:60,description:61,publishedAt:91,status:17,hook:67,tags:92,sources:93},["Date","2026-07-18T00:00:00.000Z"],[64,65,66,22],[94,95],{label:70,url:71},{label:73,url:74},[],"metiers-digitaux-2027-mesure",{id:97,data:99,body:115,filePath:116,digest:117,rendered:118},{title:100,description:101,publishedAt:102,status:17,tags:103,hook:107,sources:108},"Les métiers digitaux de 2027 : la mesure devient un poste, pas une case","Traffic managers, growth, data — qui pilote vraiment le signal ? Fiction éditoriale Jannah Mag sur l’évolution des rôles.",["Date","2026-07-29T00:00:00.000Z"],[104,105,106,22],"métiers","organisation","mesure","Les organigrammes parlent encore d’acquisition. Les comités, eux, demandent déjà : ‘est-ce qu’on peut croire ces chiffres ?’",[109,112],{label:110,url:111},"Google — Career certificates / Digital Marketing (réf. marché compétences)","https://grow.google/certificates/digital-marketing-ecommerce/",{label:113,url:114},"CNIL — cookies et traceurs (cadre métier privacy)","https://www.cnil.fr/fr/cookies-et-autres-traceurs","**Contenu fictif / illustratif** — chiffres et “études” inventés pour le Mag ; à remplacer par de vraies sources terrain.\n\n## Ce que les fiches de poste ne disent pas\n\nEn 2027 (scénario Mag), trois profils se marchent sur les pieds :\n\n1. **Growth** — veut plus de volume et d’expés.\n2. **Data** — veut des modèles propres.\n3. **Measurement** — veut un dataLayer qui ne ment pas.\n\nSans ce troisième rôle (ou casquette), les deux premiers optimisent du bruit.\n\n## Signal faible → décision chère\n\nScénario fictif *Pulse Mobile* : +18 % de “conversions” GA4 après refonte… dont 40 % d’événements doublons. Le métier qui aurait dû exister n’était pas “plus de media”, c’était **qualité de collecte**.\n\n## Et pour Studio Jannah ?\n\nFormer les équipes à lire un plan de taggage comme on lit un P&L. Les métiers de demain digitaux ne sont pas seulement créatifs ou media : ils sont **instrumentés**.","content/insights/metiers-digitaux-2027-mesure.md","b40550e0d54f73ae",{html:119,metadata:120},"<p><strong>Contenu fictif / illustratif</strong> — chiffres et “études” inventés pour le Mag ; à remplacer par de vraies sources terrain.</p>\n<h2 id=\"ce-que-les-fiches-de-poste-ne-disent-pas\">Ce que les fiches de poste ne disent pas</h2>\n<p>En 2027 (scénario Mag), trois profils se marchent sur les pieds :</p>\n<ol>\n<li><strong>Growth</strong> — veut plus de volume et d’expés.</li>\n<li><strong>Data</strong> — veut des modèles propres.</li>\n<li><strong>Measurement</strong> — veut un dataLayer qui ne ment pas.</li>\n</ol>\n<p>Sans ce troisième rôle (ou casquette), les deux premiers optimisent du bruit.</p>\n<h2 id=\"signal-faible--décision-chère\">Signal faible → décision chère</h2>\n<p>Scénario fictif <em>Pulse Mobile</em> : +18 % de “conversions” GA4 après refonte… dont 40 % d’événements doublons. Le métier qui aurait dû exister n’était pas “plus de media”, c’était <strong>qualité de collecte</strong>.</p>\n<h2 id=\"et-pour-studio-jannah\">Et pour Studio Jannah ?</h2>\n<p>Former les équipes à lire un plan de taggage comme on lit un P&#x26;L. Les métiers de demain digitaux ne sont pas seulement créatifs ou media : ils sont <strong>instrumentés</strong>.</p>",{headings:121,localImagePaths:131,remoteImagePaths:132,frontmatter:133,imagePaths:139},[122,125,128],{depth:39,slug:123,text:124},"ce-que-les-fiches-de-poste-ne-disent-pas","Ce que les fiches de poste ne disent pas",{depth:39,slug:126,text:127},"signal-faible--décision-chère","Signal faible → décision chère",{depth:39,slug:129,text:130},"et-pour-studio-jannah","Et pour Studio Jannah ?",[],[],{title:100,description:101,publishedAt:134,status:17,hook:107,tags:135,sources:136},["Date","2026-07-29T00:00:00.000Z"],[104,105,106,22],[137,138],{label:110,url:111},{label:113,url:114},[],"spa-cmp-funnel-gonfle",{id:140,data:142,body:158,filePath:159,digest:160,rendered:161},{title:143,description:144,publishedAt:145,status:17,tags:146,hook:150,sources:151},"Cross-domain SPA + CMP : pourquoi votre funnel ‘4 steps’ en affiche 11","Virtual pageviews, consent delayed, history API — cas Mag fictif sur les SPA qui gonflent les tunnels.",["Date","2026-07-12T00:00:00.000Z"],[147,148,149,22],"spa","virtual-pages","cmp","Le produit voit 4 écrans. GA4 en voit 11. Les deux ont raison — et c’est exactement le problème.",[152,155],{label:153,url:154},"Google — Measure single-page applications","https://developers.google.com/analytics/devguides/collection/ga4/single-page-applications",{label:156,url:157},"MDN — History API","https://developer.mozilla.org/en-US/docs/Web/API/History_API","**Contenu fictif / illustratif.**\n\n## Symptômes (marque placeholder *Glassfix*)\n\n- Taux d’entrée step 2 > 100 % des step 1.\n- Rebonds “étranges” après acceptation CMP.\n- Double comptage à chaque `pushState`.\n\n## Correctifs Mag\n\n1. Convention unique `virtual_page_view` (path + title).\n2. Ne pas tracker le funnel avant consent analytics.\n3. Dedup : un step = un event métier, pas un page_view par animation.\n\nStudio Jannah instrumente les SPA comme des **produits**, avec contrat d’events versionné.","content/insights/spa-cmp-funnel-gonfle.md","0a6b39becc16b495",{html:162,metadata:163},"<p><strong>Contenu fictif / illustratif.</strong></p>\n<h2 id=\"symptômes-marque-placeholder-glassfix\">Symptômes (marque placeholder <em>Glassfix</em>)</h2>\n<ul>\n<li>Taux d’entrée step 2 > 100 % des step 1.</li>\n<li>Rebonds “étranges” après acceptation CMP.</li>\n<li>Double comptage à chaque <code>pushState</code>.</li>\n</ul>\n<h2 id=\"correctifs-mag\">Correctifs Mag</h2>\n<ol>\n<li>Convention unique <code>virtual_page_view</code> (path + title).</li>\n<li>Ne pas tracker le funnel avant consent analytics.</li>\n<li>Dedup : un step = un event métier, pas un page_view par animation.</li>\n</ol>\n<p>Studio Jannah instrumente les SPA comme des <strong>produits</strong>, avec contrat d’events versionné.</p>",{headings:164,localImagePaths:171,remoteImagePaths:172,frontmatter:173,imagePaths:179},[165,168],{depth:39,slug:166,text:167},"symptômes-marque-placeholder-glassfix","Symptômes (marque placeholder Glassfix)",{depth:39,slug:169,text:170},"correctifs-mag","Correctifs Mag",[],[],{title:143,description:144,publishedAt:174,status:17,hook:150,tags:175,sources:176},["Date","2026-07-12T00:00:00.000Z"],[147,148,149,22],[177,178],{label:153,url:154},{label:156,url:157},[],"serverside-musthave-produit",{id:180,data:182,body:198,filePath:199,digest:200,rendered:201},{title:183,description:184,publishedAt:185,status:17,tags:186,hook:190,sources:191},"Server-side tracking : le nouveau ‘must-have produit’, pas un luxe tech","Pourquoi sGTM et collectes first-party deviennent une attente produit — article Mag fictif, angle mesure.",["Date","2026-07-27T00:00:00.000Z"],[187,188,189,22],"server-side","sgtm","produit","Vos équipes media demandent plus de signaux. Votre CMP en retire. Le server-side n’est plus un projet IT : c’est un arbitrage produit.",[192,195],{label:193,url:194},"Google — Server-side tagging overview","https://developers.google.com/tag-platform/tag-manager/server-side",{label:196,url:197},"Google — Consent Mode","https://developers.google.com/tag-platform/security/guides/consent","**Contenu fictif / illustratif** Jannah Mag.\n\n## Le produit “invisible”\n\nTant que le tracking est une dette GTM dans un coin, personne n’en parle. Le jour où les enchères baissent faute de conversions fiables, tout le monde découvre le **server-side**.\n\n## Trois promesses (et une limite)\n\n| Promesse | Réalité Mag (fictive) |\n|----------|------------------------|\n| Plus de signaux | Oui si consent + mapping OK |\n| Moins de fuite navigateur | Oui, pas un permis de tout tracker |\n| Meilleure perf web | Souvent, si on déplace le poids JS |\n\nLimite : un sGTM mal documenté = boîte noire. Pire qu’un GTM web sale.\n\n## Chute mesure\n\nAvant d’acheter un “produit server-side”, exigez : plan d’events, schéma BigQuery, owners, et tests de non-régression. Studio Jannah traite sGTM comme une **release produit**, pas un plugin.","content/insights/serverside-musthave-produit.md","afb6445db51fd0d6",{html:202,metadata:203},"<p><strong>Contenu fictif / illustratif</strong> Jannah Mag.</p>\n<h2 id=\"le-produit-invisible\">Le produit “invisible”</h2>\n<p>Tant que le tracking est une dette GTM dans un coin, personne n’en parle. Le jour où les enchères baissent faute de conversions fiables, tout le monde découvre le <strong>server-side</strong>.</p>\n<h2 id=\"trois-promesses-et-une-limite\">Trois promesses (et une limite)</h2>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Promesse</th><th>Réalité Mag (fictive)</th></tr></thead><tbody><tr><td>Plus de signaux</td><td>Oui si consent + mapping OK</td></tr><tr><td>Moins de fuite navigateur</td><td>Oui, pas un permis de tout tracker</td></tr><tr><td>Meilleure perf web</td><td>Souvent, si on déplace le poids JS</td></tr></tbody></table>\n<p>Limite : un sGTM mal documenté = boîte noire. Pire qu’un GTM web sale.</p>\n<h2 id=\"chute-mesure\">Chute mesure</h2>\n<p>Avant d’acheter un “produit server-side”, exigez : plan d’events, schéma BigQuery, owners, et tests de non-régression. Studio Jannah traite sGTM comme une <strong>release produit</strong>, pas un plugin.</p>",{headings:204,localImagePaths:214,remoteImagePaths:215,frontmatter:216,imagePaths:222},[205,208,211],{depth:39,slug:206,text:207},"le-produit-invisible","Le produit “invisible”",{depth:39,slug:209,text:210},"trois-promesses-et-une-limite","Trois promesses (et une limite)",{depth:39,slug:212,text:213},"chute-mesure","Chute mesure",[],[],{title:183,description:184,publishedAt:217,status:17,hook:190,tags:218,sources:219},["Date","2026-07-27T00:00:00.000Z"],[187,188,189,22],[220,221],{label:193,url:194},{label:196,url:197},[],"consent-mode-green-red",{id:223,data:225,body:239,filePath:240,digest:241,rendered:242},{title:226,description:227,publishedAt:228,status:17,tags:229,hook:233,sources:234},"Consent Mode v2 : green light GTM, red flag data quality","Avoir Consent Mode ‘bien configuré’ ne veut pas dire que vos dashboards sont justes — pièce Mag fictive.",["Date","2026-07-21T00:00:00.000Z"],[230,231,232,22],"consent","gtm","data-quality","Votre container est ‘Consent Mode ready’. Vos réunions, elles, comparent encore des pommes et des poires post-CMP.",[235,237],{label:236,url:197},"Google — Consent Mode v2",{label:238,url:114},"CNIL — cookies et autres traceurs","**Contenu fictif / illustratif** Jannah Mag.\n\n## Deux vérités qui coexistent\n\n- **GTM** peut recevoir des signaux Consent Mode impeccables.\n- **Votre reporting** peut quand même être incomparable mois à mois (opt-in variable, modelisation, tags qui fuient).\n\n## Checklist Mag (à voler)\n\n1. Taux d’opt-in analytics par device / pays (fictif cible Mag : le suivre chaque semaine).\n2. Écart GA4 vs back-office sur les commandes.\n3. Tags marketing vraiment gated (test refus total).\n4. Documentation : qui a le droit de lire quoi après refus.\n\n## Position Studio Jannah\n\nOn ne “installe” pas Consent Mode : on **pilote** l’écart entre conformité et pilotage business. Sinon vous avez une CMP jolie et des décisions fausses.","content/insights/consent-mode-green-red.md","b359d19c6ceca730",{html:243,metadata:244},"<p><strong>Contenu fictif / illustratif</strong> Jannah Mag.</p>\n<h2 id=\"deux-vérités-qui-coexistent\">Deux vérités qui coexistent</h2>\n<ul>\n<li><strong>GTM</strong> peut recevoir des signaux Consent Mode impeccables.</li>\n<li><strong>Votre reporting</strong> peut quand même être incomparable mois à mois (opt-in variable, modelisation, tags qui fuient).</li>\n</ul>\n<h2 id=\"checklist-mag-à-voler\">Checklist Mag (à voler)</h2>\n<ol>\n<li>Taux d’opt-in analytics par device / pays (fictif cible Mag : le suivre chaque semaine).</li>\n<li>Écart GA4 vs back-office sur les commandes.</li>\n<li>Tags marketing vraiment gated (test refus total).</li>\n<li>Documentation : qui a le droit de lire quoi après refus.</li>\n</ol>\n<h2 id=\"position-studio-jannah\">Position Studio Jannah</h2>\n<p>On ne “installe” pas Consent Mode : on <strong>pilote</strong> l’écart entre conformité et pilotage business. Sinon vous avez une CMP jolie et des décisions fausses.</p>",{headings:245,localImagePaths:255,remoteImagePaths:256,frontmatter:257,imagePaths:263},[246,249,252],{depth:39,slug:247,text:248},"deux-vérités-qui-coexistent","Deux vérités qui coexistent",{depth:39,slug:250,text:251},"checklist-mag-à-voler","Checklist Mag (à voler)",{depth:39,slug:253,text:254},"position-studio-jannah","Position Studio Jannah",[],[],{title:226,description:227,publishedAt:258,status:17,hook:233,tags:259,sources:260},["Date","2026-07-21T00:00:00.000Z"],[230,231,232,22],[261,262],{label:236,url:197},{label:238,url:114},[],"trafic-demain-mesure",{id:264,data:266,body:279,filePath:280,digest:281,rendered:282},{title:267,description:268,publishedAt:269,status:17,tags:270,hook:272,sources:273},"Le trafic de demain ne ressemble pas à celui d’hier — votre mesure non plus","AI Overviews, zéro-clic et réponses LLM changent l’acquisition. Voici ce que ça implique pour le tracking, l’attribution et la qualité du signal.",["Date","2026-07-31T00:00:00.000Z"],[20,271,106,19],"trafic","Quand les clics baissent, la tentation est de blâmer le SEO. Souvent, c’est la mesure qui ment en premier.",[274,276],{label:275,url:30},"Empirik — ère du zéro-clic / GEO",{label:277,url:278},"Google — AI features & web (documentation Search)","https://developers.google.com/search/docs/appearance/ai-features","Les moteurs et assistants IA synthétisent de plus en plus de réponses **sans clic**. Une part du “trafic de demain” ne passera jamais par une session GA4 classique — ou y arrivera déjà convaincue, plus courte, plus exigeante.\n\n> **Jannah Mag — contenu en partie illustratif** : angles éditoriaux à fact-checker / enrichir avec vos data réelles.\n\n## Ce qui change vraiment pour les équipes digitales\n\n- Moins de volume organique “découverte”, plus de visites à forte intention (ou aucune visite du tout).\n- Des parcours multi-surfaces (LLM → site → tunnel) mal collés par le last-click.\n- Des métiers qui basculent : moins “générer des sessions”, plus **fiabiliser le signal** et convertir le trafic restant (CRO + mesure).\n\n## Et pour la mesure / le tracking ?\n\n1. **Inventaire des points de contact** : citations LLM, landings campagnes, tunnels, retours PSP.\n2. **Qualité avant vanity** : events critiques, consentement, bots, cross-domain.\n3. **Réconciliation** : CRM / back-office vs analytics quand le clic disparaît.\n4. **GEO + CRO ensemble** : être cité ne suffit pas ; chaque visite doit convertir mieux.\n\n## Ce que Studio Jannah en retient\n\nAttirer l’attention sur les tendances Semrush-like est utile. Les transformer en **décisions mesurables** — tracking, attribution, expérimentation — c’est le métier de l’atelier.\n\n## Sources\n\nVoir les liens en métadonnées de cet article (frontmatter). Les chiffres sectoriels évoluent : toujours croiser avec votre propre dataLayer et vos exports métier.","content/insights/trafic-demain-mesure.md","cb8acdd72dd46dbd",{html:283,metadata:284},"<p>Les moteurs et assistants IA synthétisent de plus en plus de réponses <strong>sans clic</strong>. Une part du “trafic de demain” ne passera jamais par une session GA4 classique — ou y arrivera déjà convaincue, plus courte, plus exigeante.</p>\n<blockquote>\n<p><strong>Jannah Mag — contenu en partie illustratif</strong> : angles éditoriaux à fact-checker / enrichir avec vos data réelles.</p>\n</blockquote>\n<h2 id=\"ce-qui-change-vraiment-pour-les-équipes-digitales\">Ce qui change vraiment pour les équipes digitales</h2>\n<ul>\n<li>Moins de volume organique “découverte”, plus de visites à forte intention (ou aucune visite du tout).</li>\n<li>Des parcours multi-surfaces (LLM → site → tunnel) mal collés par le last-click.</li>\n<li>Des métiers qui basculent : moins “générer des sessions”, plus <strong>fiabiliser le signal</strong> et convertir le trafic restant (CRO + mesure).</li>\n</ul>\n<h2 id=\"et-pour-la-mesure--le-tracking\">Et pour la mesure / le tracking ?</h2>\n<ol>\n<li><strong>Inventaire des points de contact</strong> : citations LLM, landings campagnes, tunnels, retours PSP.</li>\n<li><strong>Qualité avant vanity</strong> : events critiques, consentement, bots, cross-domain.</li>\n<li><strong>Réconciliation</strong> : CRM / back-office vs analytics quand le clic disparaît.</li>\n<li><strong>GEO + CRO ensemble</strong> : être cité ne suffit pas ; chaque visite doit convertir mieux.</li>\n</ol>\n<h2 id=\"ce-que-studio-jannah-en-retient\">Ce que Studio Jannah en retient</h2>\n<p>Attirer l’attention sur les tendances Semrush-like est utile. Les transformer en <strong>décisions mesurables</strong> — tracking, attribution, expérimentation — c’est le métier de l’atelier.</p>\n<h2 id=\"sources\">Sources</h2>\n<p>Voir les liens en métadonnées de cet article (frontmatter). Les chiffres sectoriels évoluent : toujours croiser avec votre propre dataLayer et vos exports métier.</p>",{headings:285,localImagePaths:298,remoteImagePaths:299,frontmatter:300,imagePaths:306},[286,289,292,295],{depth:39,slug:287,text:288},"ce-qui-change-vraiment-pour-les-équipes-digitales","Ce qui change vraiment pour les équipes digitales",{depth:39,slug:290,text:291},"et-pour-la-mesure--le-tracking","Et pour la mesure / le tracking ?",{depth:39,slug:293,text:294},"ce-que-studio-jannah-en-retient","Ce que Studio Jannah en retient",{depth:39,slug:296,text:297},"sources","Sources",[],[],{title:267,description:268,publishedAt:301,status:17,hook:272,tags:302,sources:303},["Date","2026-07-31T00:00:00.000Z"],[20,271,106,19],[304,305],{label:275,url:30},{label:277,url:278},[],"moins-de-clics-plus-de-cro",{id:307,data:309,body:324,filePath:325,digest:326,rendered:327},{title:310,description:311,publishedAt:312,status:17,tags:313,hook:316,sources:317},"Moins de clics, plus de CRO : la règle que Semrush ne mettra pas dans votre roadmap","Quand l’acquisition se contracte, la conversion devient le levier n°1 — fiction Mag + angle expérimentation.",["Date","2026-07-24T00:00:00.000Z"],[314,271,315,22],"cro","experimentation","Attirer l’attention sur la baisse du trafic organique est facile. Tenir le CA avec moins de sessions : ça, c’est du métier.",[318,321],{label:319,url:320},"web.dev — Core Web Vitals (levier UX/CRO)","https://web.dev/articles/vitals",{label:322,url:323},"MDN — A/B testing concepts (réf. méthodo)","https://developer.mozilla.org/en-US/docs/Glossary/A/B_testing","**Contenu fictif / illustratif** — pas une étude Semrush réelle ; pastiche éditorial Mag.\n\n## Le piège “on va compenser en SEA”\n\nScénario *Clara Beauty* (placeholder) : −22 % de sessions organiques sur 6 mois (chiffre fictif). Budget ads +30 %. CAC explose. Personne n’a touché au tunnel.\n\n## Ce que le Mag retient\n\n1. Mesurer les **micro-conversions** fiables avant d’acheter du clic.\n2. Prioriser les pages qui concentrent le CA restant.\n3. A/B tester ce qui est instrumenté — sinon vous lisez des mirages.\n\n## Et la mesure dans tout ça ?\n\nSans plan de taggage CRO (clics CTA, steps funnel, erreurs paiement), l’expérimentation est du théâtre. Studio Jannah couple **qualité du signal** et **cadence de tests**.","content/insights/moins-de-clics-plus-de-cro.md","8034cdd3e93fdc5d",{html:328,metadata:329},"<p><strong>Contenu fictif / illustratif</strong> — pas une étude Semrush réelle ; pastiche éditorial Mag.</p>\n<h2 id=\"le-piège-on-va-compenser-en-sea\">Le piège “on va compenser en SEA”</h2>\n<p>Scénario <em>Clara Beauty</em> (placeholder) : −22 % de sessions organiques sur 6 mois (chiffre fictif). Budget ads +30 %. CAC explose. Personne n’a touché au tunnel.</p>\n<h2 id=\"ce-que-le-mag-retient\">Ce que le Mag retient</h2>\n<ol>\n<li>Mesurer les <strong>micro-conversions</strong> fiables avant d’acheter du clic.</li>\n<li>Prioriser les pages qui concentrent le CA restant.</li>\n<li>A/B tester ce qui est instrumenté — sinon vous lisez des mirages.</li>\n</ol>\n<h2 id=\"et-la-mesure-dans-tout-ça\">Et la mesure dans tout ça ?</h2>\n<p>Sans plan de taggage CRO (clics CTA, steps funnel, erreurs paiement), l’expérimentation est du théâtre. Studio Jannah couple <strong>qualité du signal</strong> et <strong>cadence de tests</strong>.</p>",{headings:330,localImagePaths:340,remoteImagePaths:341,frontmatter:342,imagePaths:348},[331,334,337],{depth:39,slug:332,text:333},"le-piège-on-va-compenser-en-sea","Le piège “on va compenser en SEA”",{depth:39,slug:335,text:336},"ce-que-le-mag-retient","Ce que le Mag retient",{depth:39,slug:338,text:339},"et-la-mesure-dans-tout-ça","Et la mesure dans tout ça ?",[],[],{title:310,description:311,publishedAt:343,status:17,hook:316,tags:344,sources:345},["Date","2026-07-24T00:00:00.000Z"],[314,271,315,22],[346,347],{label:319,url:320},{label:322,url:323},[],"useCases",["Map",351,352],"paiement-hors-domaine",{id:351,data:353,body:365,filePath:366,digest:367,rendered:368},{title:354,description:355,publishedAt:356,status:17,sector:357,complexity:358,themes:359,placeholderBrand:364},"Paiement hors domaine : le trou noir du funnel (et comment le réduire)","Site → page paiement autre domaine → retour. Ce que GA4 ne voit pas, ce que l’iframe / S2S / réconciliation permettent — cas type assistance / assurance.",["Date","2026-07-31T00:00:00.000Z"],"Assurance / assistance (illustration)","expert",[360,361,362,363],"cross-domain","iframe","reconciliation","paiement",true,"## Contexte\n\nMarque fictive **Haven Assist** (placeholder) : site vitrine + devis, puis redirection vers un **PSP / tunnel paiement** sur un autre domaine, puis retour thank-you.\n\n## Parcours\n\n```text\n[Site haven-assist.example]\n        │  CTA “Payer”\n        ▼\n[Paiement psp.example]  ← autre domaine, souvent iframe ou redirect\n        │  succès / échec\n        ▼\n[Retour / confirmation]  ← session parfois cassée, referrer perdu\n```\n\n## Ce que l’analytics croit voir\n\n- Beaucoup d’abandons “sur le site” alors que l’utilisateur est **chez le prestataire**.\n- Des conversions thank-you **sans** lien fiable avec la session d’origine.\n- Des modèles d’attribution qui sous-évaluent les leviers amont.\n\n## Leviers (sans magie)\n\n| Levier | Idée | Limite |\n|--------|------|--------|\n| **Redirect + paramètres / first-party** | Passer un `order_id` / `client_id` au retour | Dépend du PSP |\n| **Iframe + postMessage** | Écouter des events autorisés depuis l’iframe paiement | Politique PSP, RGPD, 3DS |\n| **Server-side / S2S** | Webhook paiement → dataLayer / BigQuery / Ads | IT + mapping IDs |\n| **Réconciliation** | Croiser CRM / back-office vs analytics | Latence, clés communes |\n\nL’iframe **ne “tracke pas tout”** toute seule : elle ouvre une possibilité technique **si** le prestataire l’autorise et si le consentement le permet.\n\n## Plan de mesure (exemple first-party)\n\nEvents illustratifs sur le domaine Studio / client (pas sur le PSP) :\n\n1. `checkout_start` — clic vers paiement  \n2. `checkout_return` — land thank-you (`status=success|fail`)  \n3. `purchase_reconciled` — après webhook / batch (S2S)\n\nVirtual pageviews possibles : `/funnel/checkout`, `/funnel/return`.\n\n## Ce que Studio Jannah apporte\n\nCartographier le trou, choisir le levier réaliste (iframe vs S2S vs réconciliation), instrumenter **sans** promettre une visibilité totale sur un domaine tiers non maîtrisé.\n\n> Illustration méthodologique — pas un cas client nominatif. Remplacer Haven Assist par de vrais contextes quand validés.","content/use-cases/paiement-hors-domaine.md","5e04d5d2f901c1a8",{html:369,metadata:370},"<h2 id=\"contexte\">Contexte</h2>\n<p>Marque fictive <strong>Haven Assist</strong> (placeholder) : site vitrine + devis, puis redirection vers un <strong>PSP / tunnel paiement</strong> sur un autre domaine, puis retour thank-you.</p>\n<h2 id=\"parcours\">Parcours</h2>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"text\"><code><span class=\"line\"><span>[Site haven-assist.example]</span></span>\n<span class=\"line\"><span>        │  CTA “Payer”</span></span>\n<span class=\"line\"><span>        ▼</span></span>\n<span class=\"line\"><span>[Paiement psp.example]  ← autre domaine, souvent iframe ou redirect</span></span>\n<span class=\"line\"><span>        │  succès / échec</span></span>\n<span class=\"line\"><span>        ▼</span></span>\n<span class=\"line\"><span>[Retour / confirmation]  ← session parfois cassée, referrer perdu</span></span></code></pre>\n<h2 id=\"ce-que-lanalytics-croit-voir\">Ce que l’analytics croit voir</h2>\n<ul>\n<li>Beaucoup d’abandons “sur le site” alors que l’utilisateur est <strong>chez le prestataire</strong>.</li>\n<li>Des conversions thank-you <strong>sans</strong> lien fiable avec la session d’origine.</li>\n<li>Des modèles d’attribution qui sous-évaluent les leviers amont.</li>\n</ul>\n<h2 id=\"leviers-sans-magie\">Leviers (sans magie)</h2>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Levier</th><th>Idée</th><th>Limite</th></tr></thead><tbody><tr><td><strong>Redirect + paramètres / first-party</strong></td><td>Passer un <code>order_id</code> / <code>client_id</code> au retour</td><td>Dépend du PSP</td></tr><tr><td><strong>Iframe + postMessage</strong></td><td>Écouter des events autorisés depuis l’iframe paiement</td><td>Politique PSP, RGPD, 3DS</td></tr><tr><td><strong>Server-side / S2S</strong></td><td>Webhook paiement → dataLayer / BigQuery / Ads</td><td>IT + mapping IDs</td></tr><tr><td><strong>Réconciliation</strong></td><td>Croiser CRM / back-office vs analytics</td><td>Latence, clés communes</td></tr></tbody></table>\n<p>L’iframe <strong>ne “tracke pas tout”</strong> toute seule : elle ouvre une possibilité technique <strong>si</strong> le prestataire l’autorise et si le consentement le permet.</p>\n<h2 id=\"plan-de-mesure-exemple-first-party\">Plan de mesure (exemple first-party)</h2>\n<p>Events illustratifs sur le domaine Studio / client (pas sur le PSP) :</p>\n<ol>\n<li><code>checkout_start</code> — clic vers paiement</li>\n<li><code>checkout_return</code> — land thank-you (<code>status=success|fail</code>)</li>\n<li><code>purchase_reconciled</code> — après webhook / batch (S2S)</li>\n</ol>\n<p>Virtual pageviews possibles : <code>/funnel/checkout</code>, <code>/funnel/return</code>.</p>\n<h2 id=\"ce-que-studio-jannah-apporte\">Ce que Studio Jannah apporte</h2>\n<p>Cartographier le trou, choisir le levier réaliste (iframe vs S2S vs réconciliation), instrumenter <strong>sans</strong> promettre une visibilité totale sur un domaine tiers non maîtrisé.</p>\n<blockquote>\n<p>Illustration méthodologique — pas un cas client nominatif. Remplacer Haven Assist par de vrais contextes quand validés.</p>\n</blockquote>",{headings:371,localImagePaths:390,remoteImagePaths:391,frontmatter:392,imagePaths:395},[372,375,378,381,384,387],{depth:39,slug:373,text:374},"contexte","Contexte",{depth:39,slug:376,text:377},"parcours","Parcours",{depth:39,slug:379,text:380},"ce-que-lanalytics-croit-voir","Ce que l’analytics croit voir",{depth:39,slug:382,text:383},"leviers-sans-magie","Leviers (sans magie)",{depth:39,slug:385,text:386},"plan-de-mesure-exemple-first-party","Plan de mesure (exemple first-party)",{depth:39,slug:388,text:389},"ce-que-studio-jannah-apporte","Ce que Studio Jannah apporte",[],[],{title:354,description:355,publishedAt:393,status:17,sector:357,complexity:358,themes:394,placeholderBrand:364},["Date","2026-07-31T00:00:00.000Z"],[360,361,362,363],[]];

